const e=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

const profiles={
  elena:{outcome:'Onboard a franchisee employee into the right portal with the right role, without creating a Harborline account.',owner:'Franchise services, IAM and the franchisee owner',decisions:['Which attributes must the sign-up flow collect for a partner?','Who assigns and removes roles for each franchisee?','Which applications share the flow, and what does each read from the token?','How is recovery handled when the credential belongs to the person?'],customize:['Define the partner attributes and the terms link in the flow.','Map app roles per application and who may request them.','Decide what a no-role sign-in shows.'],ai:'Spot partner accounts that still carry workforce licences, and roles nobody has used.',reset:'Restore Elena\'s role if it was removed in a rehearsal.'},
  samfed:{outcome:'Hold a franchisee-owned desk to the brand device standard while the franchisee keeps its own sign-in.',owner:'Endpoint engineering, IAM and the franchisee',decisions:['Which devices are enrolled regardless of who owns them?','Which domains are federated, and to whom?','Which policies apply by device group rather than by owner?','Who disables a franchise leaver, and how fast?'],customize:['Choose the kiosk device group and its policies.','Federate each franchisee domain with stable identifiers.','Agree licence responsibilities for devices and people.'],ai:'Flag franchise devices drifting from compliance and federated users with no recent sign-in.',reset:'Nothing to reset; the federated sign-in is read-only.'},
  jordan:{outcome:'Preserve Jordan’s identity continuity while replacing franchise access with intentional managed-hotel access—and support the return trip.',owner:'Property operations, HR, IAM and application owners',decisions:['Which records represent the same person, and which source is authoritative?','Which identifiers and business relationships must survive the transfer?','How should property and job scope become application permissions?','Which old-property access must end before the new access begins?'],customize:['Match people with an immutable correlation key and approved exception path.','Map property, job and effective dates into app roles, claims or access packages.','Choose a coexistence window, cutover signal and rollback boundary for each application.'],ai:'Correlate supplied records, draft a transfer plan and compare before-and-after property entitlements.',reset:'Remove replay-group membership, restore the prepared franchise and managed states and confirm no transfer task remains queued.'},
  sofia:{outcome:'Turn an approved hire into a productive first shift with a usable device, strong sign-in and role-appropriate access.',owner:'HR, endpoint engineering, IAM and Sofia’s manager',decisions:['Which hire event is trusted to start provisioning?','What must be ready before the device reaches Sofia?','Which access is required on day one, and who approves it?','Which bootstrap method leads to Sofia’s durable authentication method?'],customize:['Choose the authoritative hire event, lead time and exception owner.','Tailor Enrollment Status Page, required apps and device naming by worker type.','Define access bundles by job and property, with explicit manager additions.'],ai:'Spot missing prerequisites, compare assignments with the role baseline and explain failed setup evidence.',reset:'Revoke any disposable bootstrap method, restore the pilot device state and return Sofia to the documented starting assignments.'},
  nadia:{outcome:'Onboard a remote contractor without assuming office access, while preserving a clear owner and end date.',owner:'Procurement, remote support, endpoint engineering and IAM',decisions:['Can the complete setup finish from an ordinary home network?','Which existing authenticator can satisfy Harborline’s assurance requirement?','Who owns Nadia’s access, scope and expiration?','What evidence proves the boundary executed when the engagement ends?'],customize:['Vary application payloads and enrollment pacing for home-network conditions.','Scope external authentication methods to an explicit eligible population.','Connect contract dates to renewal, review and removal controls.'],ai:'Assess readiness evidence, identify missing ownership and prepare an expiry review with cited records.',reset:'Restore the staged contract date and assignments, remove test changes and document any device reset still required.'},
  sam:{outcome:'Give every shift a reliable sign-in and a clean handover on shared property devices.',owner:'Property operations, federation, service desk and endpoint teams',decisions:['Where should Sam authenticate, and how is the application trust verified?','Which prompts reduce risk without interrupting every task?','Who may restore a method, for which workers, and with what evidence?','What must disappear before the next worker uses the device?'],customize:['Choose federation routing and stable subject mapping per domain.','Tune session, prompt and risk policies around shift and device patterns.','Configure scoped recovery roles, kiosk cleanup and application sign-out together.'],ai:'Trace redirects, summarize policy evaluation and guide a scoped recovery or handover check.',reset:'Sign out every browser and application session, clear the shared workspace and restore the disposable authentication method.'},
  tom:{outcome:'Convert a missed contract boundary into an explainable, approved and verifiable cleanup decision.',owner:'Vendor sponsor, procurement, governance operations and IAM',decisions:['Why is Tom still enabled after the recorded end date?','Which source, scope or execution condition failed?','What action is safe to approve, and what evidence supports it?'],customize:['Select authoritative end-date sources and reconciliation tolerances.','Tune workflow scope, review cadence, escalation and sponsor behavior.','Separate recommendation, approval, execution and verification records.'],ai:'Assemble the timeline, identify the failed control boundary and prepare a reversible recommendation.',reset:'Undo only the isolated replay change, restore the prepared review case and confirm Tom’s current state before repeating the story.'},
  kwame:{outcome:'Complete departure controls across identity, sessions and applications, leaving evidence another team can verify.',owner:'HR, IAM, application owners and security operations',decisions:['Which termination signal started the departure process?','Which outcomes require separate verification beyond disabling the account?','Can the team connect the source event, identity action and business-system result?'],customize:['Order disablement, session revocation, entitlement removal and app deprovisioning.','Add exceptions for legal hold, mailbox transfer and delayed application connectors.','Correlate source, directory and application records with stable identifiers.'],ai:'Compare expected and observed outcomes, locate missing evidence and draft an exception follow-up.',reset:'Restore only the synthetic demonstration state, clear temporary replay artifacts and retain the audit trail for the next run.'},
  aiko:{outcome:'Let staff build agents that are real identities: owned, scoped to their purpose, observable in the sign-in log and retirable like a leaver.',owner:'The builder, Security, the platform team and identity governance',decisions:['Who owns each agent, and where is that recorded?','Which scopes does the purpose actually need, and who refuses the rest?','How does an agent prove what it did, and to whom?','What happens to the agent when its owner leaves?'],customize:['Define the scope catalogue as application roles on your own gateway API.','Route approval to Security or to the data owners of each scope.','Add workload identity Conditional Access and a review cadence for application role assignments.'],ai:'Correlate each agent’s registration, scopes, sign-ins and refusals into an accountability brief for its owner.',reset:'Retire rehearsal agents from Agent Studio (principal disabled, roles removed) and clear the run history.'}
};

const wholeStories={
  elena:{title:'A franchise manager—without an employee account.',story:[`Bayside hires Elena and she signs herself up with her work email. Harborline never creates a workforce account.`,`External ID verifies Elena and issues her Franchise.Manager role to the hub. The API allows hotel operations and blocks royalty statements.`,`Elena reaches the right franchise tools. When Bayside removes her role, her next token loses access.`],takeaway:'External ID gives Elena a governed franchise identity without turning her into a Harborline employee.',risk:'A successful sign-in could expose every franchise—or remain active after she leaves—if the application role is not enforced.'},
  samfed:{title:'A franchise worker on a Harborline-managed desk.',story:[`Bayside employs Sam; Harborline manages the shared front-desk device and the application it opens.`,`Entra sends Sam’s sign-in to Bayside’s HarborPass identity provider, then protects the Harborline resource with the returned identity.`,`Sam gets a named Front Desk session. Handover clears it, and a Bayside disablement blocks his next sign-in.`],takeaway:'Harborline governs the device and application while Bayside owns its worker and credential.',risk:'Harborline otherwise inherits franchise passwords and leaver tasks—or accepts an unmanaged front desk.'},
  jordan:{title:'One person moves from franchise to managed—and back.',story:[`Operations moves Jordan from a Bayside franchise to a Harborline-managed hotel on an approved date.`,`Entra correlates the person, grants the managed-property role and removes franchise-only access. The reverse process supports a future return.`,`Front Desk opens the new property for Jordan and refuses the old one. The application proves both sides of the transfer.`],takeaway:'Keep the person; replace the business relationship and its access.',risk:'Jordan could collect managed access while keeping permissions from the franchise relationship.'},
  sofia:{title:'A first day measured by useful work.',story:[`HR approves Sofia’s start date, role and location before Monday.`,`Entra creates her identity, prepares the managed device and stages her required applications. A Temporary Access Pass establishes her passkey.`,`Sofia signs in and completes a real task in the New Hire Checklist without opening a support ticket.`],takeaway:'Onboarding is complete when Sofia can work with durable authentication.',risk:'Sofia could arrive with a directory account but no usable device, applications or permanent sign-in.'},
  nadia:{title:'Remote from first sign-in to final day.',story:[`A sponsor approves Nadia’s remote contract, purpose and end date.`,`Entra connects her approved authenticator to time-bound access that works from an ordinary home network.`,`Nadia works remotely today. At expiry, a fresh application attempt and audit record prove the boundary closed.`],takeaway:'Remote access begins with an owner and ends on the approved date.',risk:'Nadia’s access could outlive the contract if expiry remains a separate manual task.'},
  sam:{title:'One attributable shift on a shared device.',story:[`Sam starts a named shift on a front-desk PC shared by the team.`,`Entra authenticates Sam and the kiosk opens only required applications. The proposed twelve-hour session policy remains report-only.`,`Front Desk shows Sam’s identity; handover removes his browser, application and local session state.`],takeaway:'Every shared-device session should be named, recoverable and completely cleared.',risk:'The next worker could inherit Sam’s access, leaving actions impossible to attribute.'},
  tom:{title:'The contract ended. Did the access?',story:[`Tom’s contract has an end date, but the live demo first checks whether his account and access actually changed.`,`Governance compares the source date, workflow execution and review result before an authorized cleanup decision is applied.`,`A fresh protected-app attempt supplies the answer: allowed or denied today. Tom’s separate supplier identity is checked separately.`],takeaway:'Configuration shows intent; a fresh application result proves the boundary.',risk:'An expired contract can coexist with working access—or with a second identity nobody removed.'},
  kwame:{title:'The departure Tom should have had.',story:[`HR records Kwame’s final day as the authoritative departure signal.`,`Entra disables sign-in, revokes sessions, removes assignments and starts downstream deprovisioning.`,`A fresh application attempt is refused, and the offboarding folio connects the HR event to every action.`],takeaway:'Offboarding is complete when the source, identity, application and evidence agree.',risk:'Disabling one account can hide surviving sessions, entitlements and downstream access.'},
  aiko:{title:'A guest request reveals a governed AI agent.',story:[`A guest asks for late checkout; Aiko’s concierge agent checks Housekeeping and Revenue to answer.`,`Entra gives the agent its own identity and only the approved application roles. A payroll request is refused.`,`The agent completes allowed work under its own audit trail and can be disabled, unassigned and retired.`],takeaway:'A useful agent also needs an owner, a narrow scope, visible refusals and a retirement path.',risk:'An agent borrowing a person’s authority cannot be independently governed or investigated.'}
};

const externalIdBridges={
  elena:{fit:'External ID is the primary identity, not a lens',workforce:'Nothing in the workforce tenant: no account, no licence, no password.',external:'Her account, her sign-up flow, her app role and her recovery all live in the external tenant.',decision:'Decide per population which door people come through; a franchisee employee should never need the workforce one.',flow:['Self-service sign-up','Role from the owner','Token decides','Nothing at head office'],question:'Which partner populations are in your workforce tenant today only because there was no other door?'},
  samfed:{fit:'Federated workforce identity on a franchisee-owned device',workforce:'The device, its policies and the federated domain are configured in the workforce tenant.',external:'The credential is verified by the franchisee\'s own identity provider; Entra consumes the assertion.',decision:'Hold the device standard centrally; leave credential ownership with the franchisee.',flow:['Franchise device enrolled','Same policies by group','Sign-in at HarborPass','Token from Entra'],question:'Whose identity provider verifies the people on devices you manage but do not own?'},
  jordan:{fit:'Transitioning worker with possible partner-facing access',workforce:'Jordan’s employee identity, lifecycle workflow, My Access packages and workforce application assignments remain in the workforce tenant.',external:'If Jordan also serves franchise or partner applications, External ID can provide a separate branded application identity. Link it to trusted business context without merging tenant populations.',decision:'Decide whether each application is workforce collaboration or customer/partner access. Preserve the person’s history, but keep employee authorization separate from external-application authorization.',flow:['Authoritative hire','Workforce identity','External app relationship','Application authorization'],question:'When Jordan changes employment type, which external applications must retain, replace or end his business relationship?'},
  sofia:{fit:'Employee journey with customer-facing touchpoints',workforce:'Sofia is an employee. Her hire, device, baseline access and durable authentication belong in the workforce tenant.',external:'External ID matters when Sofia supports or tests a customer-facing application. She should use a prepared external persona there, rather than placing her employee identity in the external tenant by default.',decision:'Use the workforce tenant for the worker and an external tenant for the customer population. Document when staff administer, support or impersonate customer experiences.',flow:['Hire signal','Workforce readiness','Customer app support','Audited boundary'],question:'How do employees support the External ID experience without becoming indistinguishable from customers?'},
  nadia:{fit:'Contractor who may cross collaboration and customer-app boundaries',workforce:'Use workforce B2B collaboration when Nadia needs Microsoft 365, enterprise applications, access packages and sponsor-governed access.',external:'Use External ID when Nadia is acting as a user of a customer or partner application with branded sign-up, app-specific profile and API authorization.',decision:'Classify the resource before choosing the tenant. The same person may hold two relationships, but each needs its own owner, effective dates and removal evidence.',flow:['Contract approved','B2B collaboration','External app identity','Expire both relationships'],question:'Which of Nadia’s resources require workforce collaboration, and which belong to a customer-facing External ID application?'},
  sam:{fit:'Shared device with separate workforce and external application sessions',workforce:'Sam’s Windows, federation, Conditional Access and operator recovery story stays in the workforce tenant.',external:'A shared kiosk may also launch a vendor or customer application backed by External ID. That application session must remain distinct from the Windows user and be cleared at handover.',decision:'Show three boundaries explicitly: device session, workforce identity and External ID application session. Each can start and end at a different time.',flow:['Shared device','Workforce sign-in','External app sign-in','Session cleanup'],question:'At shift change, how do you prove both the workforce session and every External ID application session ended?'},
  tom:{fit:'Expired contractor with access in more than one identity system',workforce:'Tom’s B2B guest, access package, review and sponsor decisions are governed in the workforce tenant.',external:'If Tom also had a vendor-portal account, External ID and the application need their own agreement expiry, account state and resource cleanup.',decision:'One contract-end event should reconcile every relationship, while each tenant and application produces separate execution evidence.',flow:['Contract ends','Workforce access removed','External relationship removed','Evidence reconciled'],question:'Would Tom still reach a customer or vendor application after his workforce guest access was removed?'},
  kwame:{fit:'Departure proof across workforce and external-facing systems',workforce:'Kwame’s employee disablement, session revocation, entitlements and downstream provisioning are verified from the workforce tenant.',external:'If he held test, partner or operational identities in an External ID application, those relationships need a separate owner and removal path.',decision:'Offboarding is complete only after the organization reconciles workforce identities, privileged support access and any external-application identities tied to the person.',flow:['Departure signal','Workforce controls','External app cleanup','Unified evidence'],question:'Which external-facing identities or delegated customer-support roles survive the employee departure process?'},
  aiko:{fit:'Agent identities across the workforce tenant and partner-facing APIs',workforce:'Agents that act inside Harborline are workforce-tenant applications with application roles, owned by staff and governed with the same reviews.',external:'Agents that a partner builds against Harborline’s APIs are External ID application identities registered through the Integration Exchange, scoped by the Partner API’s roles.',decision:'Classify the agent by who owns it and which resources it reaches. Internal agents live in the workforce tenant; partner agents live in External ID with their own credentials and scopes.',flow:['Register with an owner','Approve scopes','Validate every call','Retire and review'],question:'Which of your agents belong to your workforce tenant, and which are really partner integrations that need an external identity?'}
};

export function externalIdLens(person,context='story'){if(!['nadia','sam','samfed','tom','elena'].includes(person.id))return '';const x=externalIdBridges[person.id];if(!x)return '';return `<section class="external-lens ${context}" aria-label="External ID lens for ${e(person.name)}"><header><div><span class="external-lens-kicker">MICROSOFT ENTRA EXTERNAL ID LENS</span><h3>Where does External ID enter ${e(person.name.split(' ')[0])}’s journey?</h3></div><span class="external-lens-fit">${e(x.fit)}</span></header><div class="external-lens-flow" aria-label="Identity boundary sequence">${x.flow.map((step,i)=>`<div><b>${String(i+1).padStart(2,'0')}</b><span>${e(step)}</span>${i<x.flow.length-1?'<i>→</i>':''}</div>`).join('')}</div><div class="external-lens-columns"><article class="workforce"><span>WORKFORCE TENANT</span><h4>Employee and collaborator controls</h4><p>${e(x.workforce)}</p></article><article class="external"><span>EXTERNAL TENANT</span><h4>Customer and partner applications</h4><p>${e(x.external)}</p></article><article class="boundary"><span>DESIGN DECISION</span><h4>Keep the relationship explicit</h4><p>${e(x.decision)}</p></article></div><footer><span>ASK THE CLIENT</span><p>${e(x.question)}</p><a href="#tom-vendor/experience">Compare the vendor journey →</a><a href="#elena-franchise/experience">Compare the franchise journey →</a></footer></section>`;}

export function wholeJourney(person){const j=wholeStories[person.id];if(!j)return '';const labels=['BUSINESS CHANGE','IDENTITY RESPONSE','USER PROOF'];return `<article class="whole-journey"><div class="whole-journey-copy"><span class="eyebrow">${e(person.name)} · story at a glance</span><h3>${e(j.title)}</h3><div class="story-beats">${j.story.map((p,i)=>`<section class="story-beat"><b>0${i+1}</b><div><span>${labels[i]}</span><p>${e(p)}</p></div></section>`).join('')}</div></div><aside class="whole-journey-outcome"><div class="whole-journey-person"><img src="${e(person.portrait)}" alt="Portrait of ${e(person.name)}"><div><span>MEET THE PERSON</span><strong>${e(person.name)}</strong><small>${e(person.job)}</small></div></div><span>CLIENT TAKEAWAY</span><p>${e(j.takeaway)}</p>${j.risk?`<div class="story-risk"><span>WITHOUT THIS CONTROL</span><p>${e(j.risk)}</p></div>`:''}<hr><span>ASK THE CLIENT</span><blockquote>${e(person.question)}</blockquote></aside></article>${externalIdLens(person,'story')}`;}

const phases=[
  ['Human moment','story'],['Business decision','story'],['Architecture','architecture'],['Admin configuration','setup'],
  ['User experience','user'],['Proof','evidence'],['AI assistance','ai'],['Reset & replay','live']
];

export function journeyProgress(person,current){return `<div class="journey-progress" aria-label="${e(person.name)} journey progress"><span class="journey-progress-label">JOURNEY</span>${person.moments.map((m,i)=>`<button class="${i===current?'active':''}" data-action="moment" data-value="${i}" ${i===current?'aria-current="step"':''}><b>0${i+1}</b><span>${e(m.short)}</span></button>`).join('')}</div>`;}

export function teachingRhythm(active){return `<div class="teaching-rhythm" aria-label="Teaching sequence">${phases.map(([label,tab],i)=>`<button data-action="tab" data-value="${tab}" class="${active===tab||(i===1&&active==='story')?'active':''}"><b>${String(i+1).padStart(2,'0')}</b><span>${label}</span></button>`).join('')}</div>`;}

export function teachingLens(person,moment,index){const p=profiles[person.id];if(!p)return '';return `<section class="teaching-lens"><div class="teaching-lens-head"><div><span class="eyebrow">CLIENT CONVERSATION</span><h3>Turn this moment into a design decision.</h3></div><span>${e(p.owner)}</span></div><div class="teaching-cards"><article><span>BUSINESS OUTCOME</span><p>${e(p.outcome)}</p></article><article class="decision"><span>DECIDE WITH THE ROOM</span><p>${e(p.decisions[index]||person.question)}</p></article><article><span>PROVE THE RESULT</span><p>${e(moment.evidence)}</p></article></div><details class="customization-drawer"><summary><span><b>Deployment, customization, AI and replay</b><small>Open the implementation conversation for this moment</small></span><i>+</i></summary><div class="customization-grid"><section><span class="eyebrow">CUSTOMIZE FOR THE COMPANY</span><ul>${p.customize.map(x=>`<li>${e(x)}</li>`).join('')}</ul></section><section><span class="eyebrow">HOW AI HELPS</span><p>${e(p.ai)}</p><button class="outline" data-action="tab" data-value="ai">Open the AI workspace →</button></section><section><span class="eyebrow">RESET &amp; REPLAY</span><p>${e(p.reset)}</p><button class="outline" data-action="tab" data-value="live">Open the live stage →</button></section></div></details></section>`;}

export const lenaNarrative={
  outcome:'Let Leo reach useful supplier work through a branded External ID journey while the application enforces his real business boundary.',
  owner:'Product, procurement, IAM, application engineering and customer support',
  customizations:['Brand pages, terms, languages and collected attributes for the vendor population.','Offer local accounts, social identities or enterprise federation according to the approved trust model.','Enrich trusted company context, issue an intentional claims contract and enforce authorization in the API.','Design risk challenges, recovery, profile change, expiration and removal as one supported lifecycle.'],
  ai:'Summarize supplied sign-in and application evidence, identify the failed stage, propose the next read-only check and prepare a reversible change for approval.',
  reset:'Remove the prepared test account or entitlement only when the runbook calls for it, clear the sample session, undo isolated policy changes and verify the starting state.'
};
